<script lang="ts">
import type { Snippet } from 'svelte';
import { untrack, tick, onMount, onDestroy } from 'svelte';
import type { TutorialPanelContract } from '@unofficial-krds/contracts';
import { owned, control, resetField, ignoredKey } from './catalog-state.svelte.js';
let p: TutorialPanelContract & { help?:Snippet; openerId?:string; startActionPresent?:boolean; delegateEntry?:boolean; id?:string } = $props();
import PanelShell from './PanelShell.svelte';let narrow=$state(untrack(()=>typeof matchMedia==='function'&&matchMedia('(max-width:767px)').matches));const open=control(()=>p.open,untrack(()=>p.defaultOpen),untrack(()=>!narrow),open=>p.onOpenChange?.({open}));const panel=control<'help'|'tutorial'>(()=>p.activePanel,untrack(()=>p.defaultActivePanel),'tutorial',value=>p.onActivePanelChange?.({value}));const running=control(()=>p.running,untrack(()=>p.defaultRunning),false,()=>{});let expanded=$state<string|null>(untrack(()=>p.tasks.find(task=>task.id===p.activeTaskId&&task.steps.length)?.id??p.tasks.find(task=>task.steps.length)?.id??null));const uid=$props.id();const openerId=$derived(p.openerId??`${uid}-opener`);onMount(()=>{const media=matchMedia('(max-width:767px)');const change=()=>narrow=media.matches;change();media.addEventListener('change',change);return()=>media.removeEventListener('change',change);});const selected=$derived(p.tasks.find(task=>task.id===p.activeTaskId&&task.steps.length)||p.tasks.find(task=>task.steps.length));function start(){const task=selected;if(running.value||!task)return;const step=task.steps.find(step=>step.id===p.activeStepId)??task.steps[0];running.request(true);p.onStart?.({taskId:task.id,stepId:step.id});}function stop(){p.onStop?.({reason:'stop',running:false,returnTo:{panel:'tutorial',open:true,startActionId:p.startActionId}});}
const selectedTaskId=$derived(selected?.id??null);$effect(()=>{expanded=selectedTaskId;});
</script>
<button id={openerId} type="button" {...owned('tutorial-panel','opener',open.value?'open':'closed')} aria-expanded={open.value} onclick={()=>open.request(!open.value)}>튜토리얼 열기</button><PanelShell id={p.id} componentId="tutorial-panel" states={[open.value?'open':'closed',running.value?'running':'idle'].filter(Boolean).join(' ')} open={open.value} {narrow} title="튜토리얼" returnFocusId={openerId} fallbackFocusId={p.fallbackFocusId} delegateEntry={p.delegateEntry} initialFocusId={!running.value&&panel.value==='tutorial'?p.startActionId:undefined} onClose={()=>open.request(false)}><section><div role="tablist" aria-label="도움 패널" {...owned('tutorial-panel','tabs',running.value?'running':'idle')}><button type="button" role="tab" aria-selected={panel.value==='help'} onclick={()=>panel.request('help')}>도움말</button><button type="button" role="tab" aria-selected={panel.value==='tutorial'} onclick={()=>panel.request('tutorial')}>튜토리얼</button></div><button type="button" {...owned('tutorial-panel','close')} onclick={()=>open.request(false)}>튜토리얼 닫기</button><div hidden={panel.value!=='help'}>{#if p.help}{@render p.help()}{:else}<p>작업 도움말</p>{/if}</div><div hidden={panel.value!=='tutorial'}><h2>튜토리얼</h2>{#each p.tasks as task,i(task.id)}<section {...owned('tutorial-panel','task',task.id===p.activeTaskId&&'active-step')}><button type="button" aria-expanded={expanded===task.id} onclick={()=>{expanded=expanded===task.id?null:task.id;if(expanded&&task.id!==p.activeTaskId)p.onTaskChange?.({id:task.id});}}>{task.title}</button><ol hidden={expanded!==task.id} {...owned('tutorial-panel','step-list',task.id===p.activeTaskId&&'active-step')}>{#each task.steps as step}<li><button type="button" aria-current={step.id===p.activeStepId?'step':undefined} onclick={()=>{if(step.id!==p.activeStepId)p.onStepChange?.({id:step.id});}}>{step.title}</button></li>{/each}</ol>{#if task.id===selected?.id&&p.startActionPresent!==false}<button id={p.startActionId} type="button" disabled={running.value||!task.steps.length} {...owned('tutorial-panel','start')} onclick={start}>따라하기 시작</button>{/if}</section>{/each}</div>{#if running.value}<button type="button" {...owned('tutorial-panel','stop','running')} onclick={stop}>따라하기 중지</button>{/if}</section></PanelShell>
